import { useState, useEffect, useCallback } from 'react';
// Pastikan path folder components benar. 
// Jika file ini di src/App.js dan komponen di src/components/
import Navbar from './components/Navbar';
import ScreenDetector from './components/ScreenDetector';
import LiveMonitor from './components/LiveMonitor';
// import AlertPanel from './components/AlertPanel'; // Pastikan file ini ada
import StatsCard from './components/StatsCard';

function App() {
  const [stream, setStream] = useState(null);
  const [isDetecting, setIsDetecting] = useState(false);
  const [alerts, setAlerts] = useState([]); // Anggap saja INITIAL_ALERTS di sini
  const [newAlertId, setNewAlertId] = useState(null);

  const handleStreamStart = (newStream) => {
    setStream(newStream);
    setIsDetecting(true);
  };

  const handleStreamStop = () => {
    setStream(null);
    setIsDetecting(false);
  };

  return (
    <div className="min-h-screen bg-[#060d1a] text-white">
      <Navbar aiOnline={isDetecting} />

      <main className="container mx-auto p-4">
        {/* Header Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <StatsCard label="Total Vehicles" value="1,284" sub="+12% from last hour" />
          <StatsCard label="No Plate Detected" value="42" valueColor="#ef4444" />
          <StatsCard label="System Load" value="24%" sub="GPU: 42°C" />
          <StatsCard label="Uptime" value="14d 2h" />
        </div>

        <div className="main-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 2fr 1fr', gap: '20px' }}>
          <ScreenDetector
            onStreamStart={handleStreamStart}
            onStreamStop={handleStreamStop}
            isActive={isDetecting}
          />

          <LiveMonitor
            stream={stream}
            isActive={isDetecting}
          />

          {/* <AlertPanel alerts={alerts} newAlertId={newAlertId} /> */}
          <div className="alert-panel-placeholder">
             <p style={{color: '#94a3b8', fontSize: '12px'}}>Alert Panel Ready...</p>
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;
